const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '速度单位换算表' },
      { kind: 'text', payload: '原始值' },
      { kind: 'text', payload: '换算关系' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '换算结果' },
      { kind: 'text', payload: '90 km/h' },
      { kind: 'text', payload: 'km/h ÷ 3.6 = m/s' },
      { kind: 'text', payload: '90 ÷ 3.6' },
      { kind: 'text', payload: '25.0 m/s' },
      { kind: 'text', payload: '换算依据：1 m/s = 3.6 km/h' },
      { kind: 'text', payload: '结果保留三位有效数字' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var marginX = Math.max(24, W * 0.06);
    var titleY = Math.max(28, H * 0.10);
    var tableX = marginX;
    var tableY = H * 0.24;
    var tableW = W - 2 * marginX;
    var tableH = H * 0.42;
    var headerH = tableH * 0.36;
    var rowH = tableH - headerH;
    var tableBottom = tableY + tableH;
    var colRatios = [0.20, 0.26, 0.24, 0.30];
    var col1 = tableW * colRatios[0];
    var col2 = tableW * colRatios[1];
    var col3 = tableW * colRatios[2];
    var col4 = tableW * colRatios[3];
    var x0 = tableX;
    var x1 = x0 + col1;
    var x2 = x1 + col2;
    var x3 = x2 + col3;
    var x4 = x3 + col4;
    var headerCY = tableY + headerH / 2;
    var dataCY = tableY + headerH + rowH / 2;
    var c1 = (x0 + x1) / 2;
    var c2 = (x1 + x2) / 2;
    var c3 = (x2 + x3) / 2;
    var c4 = (x3 + x4) / 2;
    var footer1Y = tableBottom + Math.max(20, H * 0.045);
    var footer2Y = footer1Y + Math.max(18, H * 0.04);
    function rect(xa, ya, xb, yb) {
      return [['M', xa, ya], ['L', xb, ya], ['L', xb, yb], ['L', xa, yb], ['Z']];
    }
    function seg(xa, ya, xb, yb) {
      return [['M', xa, ya], ['L', xb, yb]];
    }
    var background = rect(0, 0, W, H);
    var tableFill = rect(x0, tableY, x4, tableBottom);
    var grid = [];
    grid = grid.concat(seg(x0, tableY + headerH, x4, tableY + headerH));
    grid = grid.concat(seg(x1, tableY, x1, tableBottom));
    grid = grid.concat(seg(x2, tableY, x2, tableBottom));
    grid = grid.concat(seg(x3, tableY, x3, tableBottom));
    var border = [];
    border = border.concat(seg(x0, tableY, x4, tableY));
    border = border.concat(seg(x4, tableY, x4, tableBottom));
    border = border.concat(seg(x4, tableBottom, x0, tableBottom));
    border = border.concat(seg(x0, tableBottom, x0, tableY));
    var paths = [
      { id: 'background', commands: background },
      { id: 'tableFill', commands: tableFill },
      { id: 'grid', commands: grid },
      { id: 'border', commands: border }
    ];
    var root = { type: 'group', children: [
      { type: 'path', pathId: 'background', fill: '#F5F8FC' },
      { type: 'path', pathId: 'tableFill', fill: '#FFFFFF' },
      { type: 'path', pathId: 'grid', fill: '#2B3A55', stroke: { width: 1.2 } },
      { type: 'path', pathId: 'border', fill: '#2B3A55', stroke: { width: 2 } },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: titleY }, hAlign: 'center', vAlign: 'middle', color: '#1F2A44' },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: c1, y: headerCY }, hAlign: 'center', vAlign: 'middle', color: '#1F2A44' },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: c2, y: headerCY }, hAlign: 'center', vAlign: 'middle', color: '#1F2A44' },
      { type: 'label', contentId: metrics[3].contentId, anchor: { x: c3, y: headerCY }, hAlign: 'center', vAlign: 'middle', color: '#1F2A44' },
      { type: 'label', contentId: metrics[4].contentId, anchor: { x: c4, y: headerCY }, hAlign: 'center', vAlign: 'middle', color: '#1F2A44' },
      { type: 'label', contentId: metrics[5].contentId, anchor: { x: c1, y: dataCY }, hAlign: 'center', vAlign: 'middle', color: '#111827' },
      { type: 'label', contentId: metrics[6].contentId, anchor: { x: c2, y: dataCY }, hAlign: 'center', vAlign: 'middle', color: '#111827' },
      { type: 'label', contentId: metrics[7].contentId, anchor: { x: c3, y: dataCY }, hAlign: 'center', vAlign: 'middle', color: '#111827' },
      { type: 'label', contentId: metrics[8].contentId, anchor: { x: c4, y: dataCY }, hAlign: 'center', vAlign: 'middle', color: '#111827' },
      { type: 'label', contentId: metrics[9].contentId, anchor: { x: W / 2, y: footer1Y }, hAlign: 'center', vAlign: 'middle', color: '#4B5563' },
      { type: 'label', contentId: metrics[10].contentId, anchor: { x: W / 2, y: footer2Y }, hAlign: 'center', vAlign: 'middle', color: '#4B5563' }
    ] };
    return { schemaVersion: 1, sceneId: 'unit-conversion-table', revision: input.revision, viewBox: { x: 0, y: 0, width: W, height: H }, paths: paths, root: root };
  }
};
